/**
 * Which timestamp authorities' time is trusted.
 *
 * A token that verifies only proves some key signed it. Whether stella
 * vouches for that key's time rests on three sources:
 *
 * - The qualified time-stamping services the EU trusted lists grant
 *   (eIDAS, ETSI TS 119 612), shipped in `trust/` and regenerated by
 *   `src/scripts/update-qualified-tsa-trust.ts`. A service listed by a CA
 *   certificate is a trust anchor; one listed by its timestamping unit's
 *   own certificate is pinned by that certificate's SHA-256, which keeps
 *   the hundreds of unit certificates out of the bundle.
 * - The roots of the public, non-qualified authorities documented in
 *   `.env.example` (`trust/public-tsa-roots.pem`, kept by hand with each
 *   root's source and fingerprint).
 * - `PDF_SIGNING_TSA_TRUST_PEM`, PEM text or a path to a PEM file, which
 *   adds the operator's own anchors: a root or intermediate CA, or an
 *   authority's own certificate to pin exactly that authority.
 *
 * Trust is reported, not required: a token whose chain reaches none of them
 * (see `certificationPathReachesAnchor`), such as one from a public,
 * non-qualified authority, is embedded at the same PAdES level with a
 * warning that stella could not vouch for its time.
 */

import { panic, Result } from "better-result";
import { readFileSync } from "node:fs";

import { sha256Hex as hashSha256Hex } from "@stll/sha256/bun";

import { env } from "@/api/env";
import { parseCertificate } from "@/api/lib/files/pdf-signing/certificate-chain";

import qualifiedAnchorsPath from "./trust/eu-qualified-tsa-anchors.pem" with { type: "file" };
import qualifiedUnitsPath from "./trust/eu-qualified-tsa-units.txt" with { type: "file" };
import publicRootsPath from "./trust/public-tsa-roots.pem" with { type: "file" };

const PEM_CERTIFICATE =
  /-----BEGIN CERTIFICATE-----([A-Za-z0-9+/=\s]+?)-----END CERTIFICATE-----/gu;
/** A unit line starts with the certificate's SHA-256; the rest is a note. */
const UNIT_FINGERPRINT = /^([0-9a-f]{64})\b/u;

export type TimestampTrust = {
  /** Certificates a timestamp's chain may end at. */
  anchors: readonly Uint8Array[];
  /** SHA-256 (hex) of timestamping-unit certificates trusted as they are. */
  pinnedUnits: ReadonlySet<string>;
};

/** The certificates in PEM text, DER; blocks that do not parse are skipped. */
export const parseTrustAnchors = (pem: string): Uint8Array[] =>
  [...pem.matchAll(PEM_CERTIFICATE)]
    .map(([, body]) => new Uint8Array(Buffer.from(body ?? "", "base64")))
    .filter((der) => der.byteLength > 0 && parseCertificate(der) !== null);

/** The fingerprints of a unit list; comment and blank lines carry none. */
export const parsePinnedUnits = (text: string): Set<string> =>
  new Set(
    text
      .split("\n")
      .map((line) => UNIT_FINGERPRINT.exec(line.trim())?.[1])
      .filter((fingerprint) => fingerprint !== undefined),
  );

/**
 * The operator's anchors. A value holding a PEM block is the bundle itself;
 * anything else is read as a path. An unreadable path yields no anchors, so
 * a misconfiguration fails closed: timestamps are embedded, not trusted.
 */
export const operatorTimestampTrustAnchors = (
  value: string | undefined,
): Uint8Array[] => {
  if (value === undefined || value.trim() === "") {
    return [];
  }
  if (value.includes("-----BEGIN CERTIFICATE-----")) {
    return parseTrustAnchors(value);
  }
  return Result.try(() =>
    parseTrustAnchors(readFileSync(value.trim(), "utf-8")),
  ).unwrapOr([]);
};

let shippedTrust: Promise<TimestampTrust> | undefined;

const loadShippedTrust = async (): Promise<TimestampTrust> => {
  const [qualifiedPem, unitsText, publicPem] = await Promise.all([
    Bun.file(qualifiedAnchorsPath).text(),
    Bun.file(qualifiedUnitsPath).text(),
    Bun.file(publicRootsPath).text(),
  ]);
  const qualified = parseTrustAnchors(qualifiedPem);
  const publicRoots = parseTrustAnchors(publicPem);
  const pinnedUnits = parsePinnedUnits(unitsText);
  if (
    qualified.length === 0 ||
    publicRoots.length === 0 ||
    pinnedUnits.size === 0
  ) {
    return panic("a shipped timestamp trust file is empty");
  }
  return { anchors: [...publicRoots, ...qualified], pinnedUnits };
};

/**
 * The shipped trust, read once. The files are part of the build (imported
 * as assets, so `bun build --compile` embeds them), so one that is missing
 * or empty is a broken image.
 */
export const shippedTimestampTrust = async (): Promise<TimestampTrust> =>
  await (shippedTrust ??= loadShippedTrust());

/** The shipped trust, extended by `PDF_SIGNING_TSA_TRUST_PEM`. */
export const configuredTimestampTrust = async (
  value: string | undefined = env.PDF_SIGNING_TSA_TRUST_PEM,
): Promise<TimestampTrust> => {
  const shipped = await shippedTimestampTrust();
  return {
    anchors: [...shipped.anchors, ...operatorTimestampTrustAnchors(value)],
    pinnedUnits: shipped.pinnedUnits,
  };
};

/**
 * The anchors a timestamp signed by `signerCertificate` is checked against:
 * a pinned unit certificate is its own anchor, exactly as an operator's
 * pinned authority certificate is.
 */
export const anchorsForTimestamp = (
  { anchors, pinnedUnits }: TimestampTrust,
  signerCertificate: Uint8Array,
): readonly Uint8Array[] =>
  pinnedUnits.has(hashSha256Hex(signerCertificate))
    ? [...anchors, signerCertificate]
    : anchors;
